/**
 * Returns the refund in cents when a customer gets `percent` percent of `totalCents` back.
 *
 * Rounds down to the whole cent, never to the nearest: the payment provider refuses a refund
 * that exceeds what is left of the captured amount, and rounding to the nearest cent made the
 * last of several partial refunds fail. `percent` may have up to two decimals, such as 12.5.
 */
export function computeRefund(totalCents, percent) {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new Error(`Not an amount in cents: ${totalCents}`);
  }
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
    throw new Error(`Not a percentage between 0 and 100: ${percent}`);
  }
  // Work in hundredths of a percent so the arithmetic stays in whole numbers.
  const hundredths = Math.round(percent * 100);
  return Math.floor((totalCents * hundredths) / 10_000);
}

