import assert from 'node:assert/strict';
import test from 'node:test';
import { computeRefund } from '../lib/refunds.js';

test('refunds a percentage of the total in cents', () => {
  assert.equal(computeRefund(10_000, 25), 2500);
  assert.equal(computeRefund(1850, 100), 1850);
  assert.equal(computeRefund(1850, 0), 0);
});

test('rounds down to the whole cent, never to the nearest', () => {
  assert.equal(computeRefund(999, 50), 499);
  assert.equal(computeRefund(1, 99), 0);
  assert.equal(computeRefund(1850, 33.3), 616);
});

test('rejects amounts and percentages that make no sense', () => {
  assert.throws(() => computeRefund(12.5, 10));
  assert.throws(() => computeRefund(-100, 10));
  assert.throws(() => computeRefund(100, 101));
  assert.throws(() => computeRefund(100, -1));
  assert.throws(() => computeRefund(100, Number.NaN));
});

